SELECT "Secondary endpoint"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Secondary endpoint", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Atezolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Treatment regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Monotherapy/combination", '')) = 'Combination' AND TRIM(COALESCE("Name of ICI", '')) = 'Pembrolizumab' AND TRIM(COALESCE("Type of combination", '')) = 'ICI+Chemo';

SELECT "PubMed ID"
