SELECT "Name of ICI"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Name of ICI", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Esophageal/GEJ' AND TRIM(COALESCE("Monotherapy/combination", '')) = 'Monotherapy' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

